import{_ as e,c as i,o as r,a0 as t}from"./chunks/framework.DKRgXLPU.js";const a=JSON.parse('{"title":"Introduction au jeu mental - Guide du participant","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/fr/participant-guide.md","filePath":"public/downloads/fr/participant-guide.md"}');const n=e({name:"public/downloads/fr/participant-guide.md"},[["render",function(e,a,n,o,s,l){return r(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="introduction-au-jeu-mental-guide-du-participant" tabindex="-1">Introduction au jeu mental - Guide du participant <a class="header-anchor" href="#introduction-au-jeu-mental-guide-du-participant" aria-label="Permalink to &quot;Introduction au jeu mental - Guide du participant&quot;">​</a></h1><p><strong>Académie de Pétanque</strong><em>Développement des joueurs d&#39;élite</em></p><hr><h2 id="accueillir" tabindex="-1">Accueillir <a class="header-anchor" href="#accueillir" aria-label="Permalink to &quot;Accueillir&quot;">​</a></h2><p>Aujourd&#39;hui, vous apprendrez des techniques mentales pratiques pour améliorer vos performances à la pétanque.</p><h3 id="ce-que-vous-apprendrez" tabindex="-1">Ce que vous apprendrez <a class="header-anchor" href="#ce-que-vous-apprendrez" aria-label="Permalink to &quot;Ce que vous apprendrez&quot;">​</a></h3><ul><li>Pourquoi l&#39;entraînement mental est important pour les joueurs d&#39;élite</li><li>La différence entre le « mode technique » et le « mode flux »</li><li>Comment reconnaître et gérer sa critique intérieure</li><li>Techniques simples de gestion de la pression</li><li>Une routine de base avant le tir</li></ul><hr><h2 id="l-39-etat-de-la-zone-du-flux" tabindex="-1">L&#39;état de la zone/du flux <a class="header-anchor" href="#l-39-etat-de-la-zone-du-flux" aria-label="Permalink to &quot;L&amp;#39;état de la zone/du flux&quot;">​</a></h2><h3 id="qu-39-est-ce-que-le-flow" tabindex="-1">Qu&#39;est-ce que le Flow ? <a class="header-anchor" href="#qu-39-est-ce-que-le-flow" aria-label="Permalink to &quot;Qu&amp;#39;est-ce que le Flow ?&quot;">​</a></h3><p>Le flow est cet état magique où :</p><ul><li>Tout semble sans effort</li><li>Le temps semble ralentir</li><li>Tu ne réfléchis pas, tu joues simplement.</li><li>Votre technique s&#39;exécute à la perfection.</li></ul><h3 id="deux-modes-d-39-esprit" tabindex="-1">Deux modes d&#39;esprit <a class="header-anchor" href="#deux-modes-d-39-esprit" aria-label="Permalink to &quot;Deux modes d&amp;#39;esprit&quot;">​</a></h3><p><strong>Mode de planification (analytique)</strong></p><ul><li>Analyse du terrain</li><li>Choisir sa stratégie</li><li>Choisir le bon coup</li><li>Évaluation des risques</li></ul><p><strong>Mode d&#39;exécution (Flux)</strong></p><ul><li>Faire confiance à son corps</li><li>Ne pas penser à la technique</li><li>se concentrer sur le moment présent</li><li>Exécution automatique</li></ul><h3 id="l-39-interrupteur" tabindex="-1">L&#39;interrupteur <a class="header-anchor" href="#l-39-interrupteur" aria-label="Permalink to &quot;L&amp;#39;interrupteur&quot;">​</a></h3><p>La compétence clé : <strong>passer du mode planification au mode exécution</strong></p><p><strong>Avant la prise de vue :</strong> Analyser, planifier, décider <strong>Pendant la prise de vue :</strong> Confiance, fluidité, exécution</p><hr><h2 id="le-critique-interieur-contre-le-coach-interieur" tabindex="-1">Le critique intérieur contre le coach intérieur <a class="header-anchor" href="#le-critique-interieur-contre-le-coach-interieur" aria-label="Permalink to &quot;Le critique intérieur contre le coach intérieur&quot;">​</a></h2><h3 id="votre-critique-interieure-dit" tabindex="-1">Votre critique intérieure dit : <a class="header-anchor" href="#votre-critique-interieure-dit" aria-label="Permalink to &quot;Votre critique intérieure dit :&quot;">​</a></h3><ul><li>« C&#39;était terrible ! »</li><li>«Tu fais toujours des erreurs sous la pression.»</li><li>« Tout le monde te regarde échouer »</li><li>« Tu n&#39;es pas assez bon »</li></ul><h3 id="votre-coach-interieur-vous-dit" tabindex="-1">Votre coach intérieur vous dit : <a class="header-anchor" href="#votre-coach-interieur-vous-dit" aria-label="Permalink to &quot;Votre coach intérieur vous dit :&quot;">​</a></h3><ul><li>«Que puis-je en tirer comme leçon ?»</li><li>&quot;Prochaine chance, nouveau départ&quot;</li><li>« J&#39;ai déjà pris ce cliché. »</li><li>«Faites confiance au processus»</li></ul><h3 id="exercice-de-recadrage" tabindex="-1">Exercice de recadrage <a class="header-anchor" href="#exercice-de-recadrage" aria-label="Permalink to &quot;Exercice de recadrage&quot;">​</a></h3><p>Quand vous remarquez votre critique intérieure :</p><ol><li><strong>Pause</strong> - Identifier la pensée critique</li><li><strong>Recadrer</strong> - Que dirait votre entraîneur ?</li><li><strong>Réinitialisation</strong> - Prenez 3 respirations</li><li><strong>Refocus</strong> - Prise de vue suivante</li></ol><hr><h2 id="outils-pratiques" tabindex="-1">Outils pratiques <a class="header-anchor" href="#outils-pratiques" aria-label="Permalink to &quot;Outils pratiques&quot;">​</a></h2><h3 id="reinitialisation-en-3-respirations" tabindex="-1">Réinitialisation en 3 respirations <a class="header-anchor" href="#reinitialisation-en-3-respirations" aria-label="Permalink to &quot;Réinitialisation en 3 respirations&quot;">​</a></h3><p>Utilisez ceci après des erreurs ou en cas de pression :</p><ol><li><strong>Respiration 1 :</strong> Remarquez la tension (où la ressentez-vous ?)</li><li><strong>Respiration 2 :</strong> Relâchez la tension (laissez-la partir)</li><li><strong>Respiration 3 :</strong> Recentrez-vous sur le présent (cette prise de vue, ce moment précis).</li></ol><h3 id="routine-avant-le-tir" tabindex="-1">Routine avant le tir <a class="header-anchor" href="#routine-avant-le-tir" aria-label="Permalink to &quot;Routine avant le tir&quot;">​</a></h3><p>Instaurez une régularité grâce à une routine simple :</p><ol><li><strong>Visualisez</strong> - Visualisez la scène dans votre esprit.</li><li><strong>Respirez</strong> - Une grande inspiration</li><li><strong>Ancre</strong> - Touchez votre boule, sentez son poids</li><li><strong>Exécuter</strong> - Faire confiance et jeter</li></ol><h3 id="protocole-de-recuperation-des-erreurs" tabindex="-1">Protocole de récupération des erreurs <a class="header-anchor" href="#protocole-de-recuperation-des-erreurs" aria-label="Permalink to &quot;Protocole de récupération des erreurs&quot;">​</a></h3><p>Après un mauvais tir :</p><ol><li><strong>Reconnaître</strong> - « Cela ne s&#39;est pas passé comme prévu »</li><li><strong>Libération</strong> - Réinitialisation physique (secouez-vous, marchez)</li><li><strong>Se recentrer</strong> - « Chaque nouvelle opportunité est une chance à saisir »</li><li><strong>Exécuter</strong> - Faites confiance à votre routine</li></ol><hr><h2 id="votre-plan-d-39-action" tabindex="-1">Votre plan d&#39;action <a class="header-anchor" href="#votre-plan-d-39-action" aria-label="Permalink to &quot;Votre plan d&amp;#39;action&quot;">​</a></h2><h3 id="cette-semaine" tabindex="-1">Cette semaine <a class="header-anchor" href="#cette-semaine" aria-label="Permalink to &quot;Cette semaine&quot;">​</a></h3><p>Choisissez UNE technique à pratiquer :</p><ul><li>[ ] Réinitialisation en 3 respirations après chaque erreur</li><li>[ ] Routine de préparation avant chaque lancer</li><li>[ ] Recadrer une pensée de la critique intérieure par session</li><li>[ ] Entraînez-vous à passer du mode planification au mode exécution</li></ul><h3 id="suivez-vos-progres" tabindex="-1">Suivez vos progrès <a class="header-anchor" href="#suivez-vos-progres" aria-label="Permalink to &quot;Suivez vos progrès&quot;">​</a></h3><p>Avis:</p><ul><li>À quel moment vous sentez-vous le plus en état de flow ?</li><li>Qu’est-ce qui déclenche votre critique intérieure ?</li><li>Quelle technique vous aide le plus ?</li><li>Comment vos performances évoluent-elles ?</li></ul><hr><h2 id="ressources-et-prochaines-etapes" tabindex="-1">Ressources et prochaines étapes <a class="header-anchor" href="#ressources-et-prochaines-etapes" aria-label="Permalink to &quot;Ressources et prochaines étapes&quot;">​</a></h2><h3 id="poursuivre-l-39-apprentissage" tabindex="-1">Poursuivre l&#39;apprentissage <a class="header-anchor" href="#poursuivre-l-39-apprentissage" aria-label="Permalink to &quot;Poursuivre l&amp;#39;apprentissage&quot;">​</a></h3><ul><li><strong>La Zone</strong> - Plongée au cœur des états de flow</li><li><strong>Force mentale</strong> - Gestion avancée du stress</li><li><strong>Modèle d&#39;objectif</strong> - Structurez votre développement</li><li><strong>Modèle de journal</strong> - Suivez vos progrès</li></ul><h3 id="pratique-quotidienne" tabindex="-1">Pratique quotidienne <a class="header-anchor" href="#pratique-quotidienne" aria-label="Permalink to &quot;Pratique quotidienne&quot;">​</a></h3><ul><li>5 minutes de respiration consciente</li><li>Visualisez les tirs réussis</li><li>Entraînez-vous à votre routine d&#39;avant-tir.</li><li>Recadrer les pensées négatives</li></ul><hr><h2 id="points-cles-a-retenir" tabindex="-1">Points clés à retenir <a class="header-anchor" href="#points-cles-a-retenir" aria-label="Permalink to &quot;Points clés à retenir&quot;">​</a></h2><ol><li><strong>L&#39;état de flow est accessible</strong> - Vous pouvez apprendre à y accéder plus régulièrement.</li><li><strong>Votre voix intérieure compte</strong> - Encouragez-vous, ne vous critiquez pas.</li><li><strong>Des outils simples qui fonctionnent</strong> - 3 respirations, une routine, une réinitialisation</li><li><strong>La pratique est essentielle</strong> - Les compétences mentales nécessitent un entraînement, tout comme les compétences techniques.</li></ol><hr><p><strong>N&#39;oubliez pas :</strong> L&#39;entraînement mental ne se résume pas à la pensée positive. Il s&#39;agit de techniques pratiques qui vous aident à atteindre votre meilleur niveau de performance sous pression.</p><hr><p><em>Visitez carreau.app pour plus de ressources</em><em>Académie de Pétanque - Développement des joueurs élites</em></p>',61)])])}]]);export{a as __pageData,n as default};
